import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Handler;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class SayNoDemo {

    private static final Logger log = Logger.getLogger(SayNoDemo.class.getName());
    static final String BANK_NAME = "National Bank of India";

    static {
        Logger rootLogger = Logger.getLogger("");
        for (Handler handler : rootLogger.getHandlers()) {
            rootLogger.removeHandler(handler);
        }
        ConsoleHandler consoleHandler = new ConsoleHandler();
        consoleHandler.setFormatter(new BankLogFormatter());
        consoleHandler.setLevel(Level.ALL);
        rootLogger.addHandler(consoleHandler);
        rootLogger.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        log.info(() -> "Evaluating a stakeholder feature request at " + BANK_NAME);

        RequestEvaluator evaluator = new RequestEvaluator(true);

        // The risky ask: skip fraud check on large transfers. High benefit, but weakens safety.
        FeatureRequest skipFraud = new FeatureRequest(
                "Skip fraud check on large transfers", 8, 9, true);

        // The safer alternative that meets the real need (speed) without weakening safety.
        FeatureRequest asyncFraud = new FeatureRequest(
                "Async fraud scoring — keep the check, hide its latency", 7, 2, false);

        evaluator.evaluate(skipFraud);
        evaluator.evaluate(asyncFraud);
    }
}

// ─── Would be in model/FeatureRequest.java in a real project ───
class FeatureRequest {
    private final String description;
    private final int benefitScore;   // 0-10
    private final int riskScore;       // 0-10
    private final boolean weakensSafetyControl;

    FeatureRequest(String description, int benefitScore, int riskScore,
                   boolean weakensSafetyControl) {
        this.description = description;
        this.benefitScore = benefitScore;
        this.riskScore = riskScore;
        this.weakensSafetyControl = weakensSafetyControl;
    }

    String getDescription() { return description; }
    int getBenefitScore() { return benefitScore; }
    int getRiskScore() { return riskScore; }
    boolean weakensSafetyControl() { return weakensSafetyControl; }
}

// ─── Would be in eval/RequestEvaluator.java in a real project ───
class RequestEvaluator {
    private static final Logger log = Logger.getLogger(RequestEvaluator.class.getName());
    private final boolean blockIfWeakensSafety;

    RequestEvaluator(boolean blockIfWeakensSafety) {
        this.blockIfWeakensSafety = blockIfWeakensSafety;
    }

    boolean evaluate(FeatureRequest req) {
        if (blockIfWeakensSafety && req.weakensSafetyControl()) {
            log.warning(() -> "DECLINE: '" + req.getDescription()
                    + "' weakens a safety-critical control (fraud). Benefit "
                    + req.getBenefitScore() + " does not justify risk "
                    + req.getRiskScore() + ". Propose a safer alternative.");
            return false;
        }
        if (req.getBenefitScore() > req.getRiskScore()) {
            log.info(() -> "APPROVE: '" + req.getDescription() + "' benefit "
                    + req.getBenefitScore() + " outweighs risk " + req.getRiskScore() + ".");
            return true;
        }
        log.warning(() -> "DECLINE: '" + req.getDescription() + "' risk "
                + req.getRiskScore() + " outweighs benefit " + req.getBenefitScore() + ".");
        return false;
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("%1$tY-%1$tm-%1$td %1$tH:%1$tM:%1$tS.%1$tL %2$-7s [%3$s] %4$s%n",
                record.getMillis(),
                record.getLevel().getName(),
                record.getSourceClassName() != null
                        ? record.getSourceClassName().substring(
                                record.getSourceClassName().lastIndexOf('.') + 1)
                        : "Unknown",
                record.getMessage());
    }
}
